#!/usr/bin/env python3
import sys, json, re, math, datetime

MAX_FLOAT = 1.7976931348623157e+308

class ConvError(Exception):
    pass

class HCLWriteError(Exception):
    pass

# ---------------- common helpers ----------------

def is_nan(x): return isinstance(x, float) and math.isnan(x)
def is_inf(x): return isinstance(x, float) and math.isinf(x)

def decode_escapes(s):
    try:
        return bytes(s, 'utf-8').decode('unicode_escape')
    except Exception:
        return s

def split_top(s, sep=','):
    parts=[]; cur=[]; stack=[]; quote=None; esc=False
    for ch in s:
        if quote:
            cur.append(ch)
            if esc:
                esc=False
            elif quote=='"' and ch=='\\':
                esc=True
            elif ch==quote:
                quote=None
            continue
        if ch in ('"', "'"):
            quote=ch; cur.append(ch); continue
        if ch in '[{(':
            stack.append(ch); cur.append(ch); continue
        if ch in ']})':
            if stack: stack.pop()
            cur.append(ch); continue
        if ch==sep and not stack:
            parts.append(''.join(cur).strip()); cur=[]
        else:
            cur.append(ch)
    parts.append(''.join(cur).strip())
    return parts

def find_top(s, target):
    stack=[]; quote=None; esc=False
    for i,ch in enumerate(s):
        if quote:
            if esc: esc=False
            elif quote=='"' and ch=='\\': esc=True
            elif ch==quote: quote=None
            continue
        if ch in ('"', "'"):
            quote=ch; continue
        if ch in '[{(':
            stack.append(ch); continue
        if ch in ']})':
            if stack: stack.pop()
            continue
        if ch==target and not stack:
            return i
    return -1

def strip_comment(s):
    out=[]; quote=None; esc=False; i=0
    while i < len(s):
        ch=s[i]
        if quote:
            out.append(ch)
            if esc:
                esc=False
            elif quote=='"' and ch=='\\':
                esc=True
            elif ch==quote:
                quote=None
            i+=1; continue
        if ch in ('"', "'"):
            quote=ch; out.append(ch); i+=1; continue
        if ch=='#':
            break
        if ch=='/' and i+1<len(s) and s[i+1]=='/':
            break
        out.append(ch); i+=1
    return ''.join(out).rstrip()

def parse_json_text(text):
    try:
        return json.loads(text, object_pairs_hook=dict)
    except json.JSONDecodeError as e:
        msg = e.msg
        # Python and Go differ slightly for empty input; keep useful message.
        if not text.strip():
            msg = "unexpected end of JSON input"
        raise ConvError("Error parsing JSON: " + msg)

# ---------------- JSON writer ----------------

def go_float_str(f):
    if math.isnan(f): return 'NaN'
    if math.isinf(f): return '+Inf' if f>0 else '-Inf'
    if f == 0: return '0'
    # Go's encoding/json uses the shortest decimal representation. Python's .15g/.17g is close;
    # use integer form for integral floats to match the common Go output.
    if f.is_integer() and abs(f) < 1e21:
        return str(int(f))
    s = format(f, '.15g')
    if 'e' in s:
        mant, exp = s.split('e')
        sign = '+' if int(exp) >= 0 else '-'
        s = mant + 'e' + sign + str(abs(int(exp)))
    return s

def json_string(s, escape_html=False):
    out='"'
    for ch in s:
        o=ord(ch)
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\b': out+='\\b'
        elif ch=='\f': out+='\\f'
        elif ch=='\n': out+='\\n'
        elif ch=='\r': out+='\\r'
        elif ch=='\t': out+='\\t'
        elif o < 0x20:
            out+='\\u%04x'%o
        elif ch=='<' and escape_html: out+='\\u003c'
        elif ch=='>' and escape_html: out+='\\u003e'
        elif ch=='&' and escape_html: out+='\\u0026'
        elif o in (0x2028,0x2029):
            out+='\\u%04x'%o
        else:
            out+=ch
    return out+'"'

def prepare_json_value(v, no_convert=False):
    if isinstance(v, dict):
        return {str(k): prepare_json_value(val, no_convert) for k,val in v.items()}
    if isinstance(v, list):
        return [prepare_json_value(x, no_convert) for x in v]
    if isinstance(v, float) and (math.isnan(v) or math.isinf(v)):
        if no_convert:
            if math.isnan(v): return None
            return MAX_FLOAT if v>0 else -MAX_FLOAT
        return 'NaN' if math.isnan(v) else ('Infinity' if v>0 else '-Infinity')
    return v

def dump_json(v, indent=False, escape_html=False):
    def enc(x, level=0):
        sp='  '*level
        if x is None: return 'null'
        if x is True: return 'true'
        if x is False: return 'false'
        if isinstance(x, int) and not isinstance(x,bool): return str(x)
        if isinstance(x, float): return go_float_str(x)
        if isinstance(x, str): return json_string(x, escape_html)
        if isinstance(x, list):
            if not x: return '[]'
            if not indent: return '['+','.join(enc(i, level) for i in x)+']'
            return '[\n' + ',\n'.join('  '*(level+1)+enc(i, level+1) for i in x) + '\n' + sp + ']'
        if isinstance(x, dict):
            if not x: return '{}'
            items=[]
            for k,val in x.items():
                if indent:
                    items.append('  '*(level+1)+json_string(str(k), escape_html)+': '+enc(val, level+1))
                else:
                    items.append(json_string(str(k), escape_html)+':'+enc(val, level))
            if not indent: return '{'+','.join(items)+'}'
            return '{\n' + ',\n'.join(items) + '\n' + sp + '}'
        return json_string(str(x), escape_html)
    return enc(v)+'\n'

# ---------------- YAML parser ----------------

class YAMLParser:
    def __init__(self, text):
        self.raw = text.splitlines()
        self.lines=[]; self.anchors={}
        self._prep()
    def _prep(self):
        i=0
        while i < len(self.raw):
            raw=self.raw[i].rstrip('\r')
            if raw.strip() in ('---','...'):
                i+=1; continue
            if not raw.strip() or raw.lstrip().startswith('#'):
                i+=1; continue
            ind=len(raw)-len(raw.lstrip(' '))
            s=strip_comment(raw[ind:])
            if s.strip():
                self.lines.append((ind,s.strip(),i+1))
            i+=1
    def parse(self):
        if not self.lines:
            return None
        val, idx = self.parse_block(0, self.lines[0][0])
        return val
    def parse_block(self, idx, indent):
        if idx>=len(self.lines): return None, idx
        ind, content, _ = self.lines[idx]
        if content.startswith('- '):
            return self.parse_seq(idx, ind)
        return self.parse_map(idx, ind)
    def parse_seq(self, idx, indent):
        arr=[]
        while idx < len(self.lines):
            ind, content, _ = self.lines[idx]
            if ind != indent or not content.startswith('- '): break
            rest=content[2:].strip()
            idx += 1
            if rest=='':
                if idx < len(self.lines) and self.lines[idx][0] > indent:
                    val, idx = self.parse_block(idx, self.lines[idx][0])
                else:
                    val=None
                arr.append(val); continue
            # inline map item, e.g. - a: b
            pos = self.find_yaml_colon(rest)
            if pos >= 0 and not rest.startswith(('{','[')):
                keytxt=rest[:pos].strip(); valtxt=rest[pos+1:].strip()
                d={self.parse_key(keytxt): self.parse_value_after_colon(valtxt, idx, indent)}
                if valtxt=='' and idx < len(self.lines) and self.lines[idx][0] > indent:
                    d[list(d.keys())[0]], idx = self.parse_block(idx, self.lines[idx][0])
                if idx < len(self.lines) and self.lines[idx][0] > indent:
                    more, idx2 = self.parse_map(idx, self.lines[idx][0])
                    if isinstance(more, dict):
                        d.update(more); idx=idx2
                arr.append(d)
            else:
                arr.append(self.parse_inline(rest))
                # discard/ignore unexpected continuation for scalar
        return arr, idx
    def parse_map(self, idx, indent):
        d={}
        while idx < len(self.lines):
            ind, content, _ = self.lines[idx]
            if ind < indent: break
            if ind != indent: break
            if content.startswith('- '): break
            pos=self.find_yaml_colon(content)
            if pos < 0:
                # a bare scalar at top level
                return self.parse_inline(content), idx+1
            key=self.parse_key(content[:pos].strip())
            valtxt=content[pos+1:].strip()
            idx += 1
            if valtxt in ('|','|-','|+','>','>-','>+'):
                block=[]
                minind=None; start=idx
                while idx < len(self.lines) and self.lines[idx][0] > indent:
                    minind = self.lines[idx][0] if minind is None else min(minind,self.lines[idx][0])
                    idx += 1
                for j in range(start, idx):
                    raw = self.raw[self.lines[j][2]-1]
                    block.append(raw[minind:] if minind is not None and len(raw)>=minind else raw.lstrip())
                text='\n'.join(block)
                if valtxt.startswith('>'):
                    text=' '.join(x.strip() for x in block)
                if not valtxt.endswith('-'):
                    text+='\n'
                d[key]=text
            elif valtxt=='':
                if idx < len(self.lines) and self.lines[idx][0] > indent:
                    d[key], idx = self.parse_block(idx, self.lines[idx][0])
                else:
                    d[key]=None
            else:
                d[key]=self.parse_inline(valtxt)
        return d, idx
    def find_yaml_colon(self, s):
        stack=[]; quote=None; esc=False
        for i,ch in enumerate(s):
            if quote:
                if esc: esc=False
                elif quote=='"' and ch=='\\': esc=True
                elif ch==quote: quote=None
                continue
            if ch in ('"',"'"):
                quote=ch; continue
            if ch in '[{(': stack.append(ch); continue
            if ch in ']})':
                if stack: stack.pop()
                continue
            if ch==':' and not stack:
                # YAML key separator: colon followed by end or whitespace
                if i==len(s)-1 or s[i+1].isspace(): return i
        return -1
    def parse_key(self,s):
        return self.parse_inline(s)
    def parse_value_after_colon(self, valtxt, idx, indent):
        if valtxt=='': return None
        return self.parse_inline(valtxt)
    def parse_inline(self, s):
        s=s.strip()
        if not s: return None
        m=re.match(r'^&([A-Za-z0-9_\-]+)\s*(.*)$', s)
        if m:
            val=self.parse_inline(m.group(2)) if m.group(2).strip() else None
            self.anchors[m.group(1)] = val
            return val
        if s.startswith('*') and s[1:] in self.anchors:
            return self.anchors[s[1:]]
        if s.startswith('[') and s.endswith(']'):
            inner=s[1:-1].strip()
            if not inner: return []
            return [self.parse_inline(p) for p in split_top(inner)]
        if s.startswith('{') and s.endswith('}'):
            inner=s[1:-1].strip(); d={}
            if not inner: return d
            for p in split_top(inner):
                pos=find_top(p, ':')
                if pos<0: continue
                d[self.parse_key(p[:pos].strip())]=self.parse_inline(p[pos+1:].strip())
            return d
        if (s.startswith('"') and s.endswith('"')):
            try: return json.loads(s)
            except Exception: return decode_escapes(s[1:-1])
        if (s.startswith("'") and s.endswith("'")):
            return s[1:-1].replace("''", "'")
        low=s.lower()
        if low in ('null','~'): return None
        if low == 'true': return True
        if low == 'false': return False
        if low in ('.nan','+.nan','-.nan'): return float('nan')
        if low in ('.inf','+.inf'): return float('inf')
        if low == '-.inf': return float('-inf')
        if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
            return s + 'T00:00:00Z'
        # timestamp: preserve as text
        if re.match(r'^\d{4}-\d{2}-\d{2}[Tt ][0-9:.+-]+Z?$', s):
            return s.replace(' ', 'T')
        num=s.replace('_','')
        try:
            if re.match(r'^[+-]?0x[0-9a-fA-F]+$', num): return int(num,16)
            if re.match(r'^[+-]?0b[01]+$', num): return int(num,2)
            if re.match(r'^[+-]?0[0-7]+$', num) and len(num.lstrip('+-'))>1: return int(num,8)
            if re.match(r'^[+-]?[0-9]+$', num): return int(num,10)
            if re.match(r'^[+-]?(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+[eE][+-]?[0-9]+|[0-9]+\.[0-9]*[eE][+-]?[0-9]+)$', num): return float(num)
        except Exception:
            pass
        return s

def parse_yaml_text(text):
    try:
        return YAMLParser(text).parse()
    except ConvError: raise
    except Exception as e:
        raise ConvError('Error parsing YAML: ' + str(e))

# ---------------- YAML writer ----------------

def special_string_to_float(s):
    if s == 'NaN': return float('nan')
    if s == 'Infinity': return float('inf')
    if s == '-Infinity': return float('-inf')
    return None

def yaml_plain_danger(s):
    low=s.lower()
    if s=='': return True
    if '\n' in s: return False
    if low in ('true','false','null','~','yes','no','on','off','y','n'):
        return True
    if s in ('NaN','Infinity','-Infinity'):
        return True
    if re.match(r'^[+-]?(?:0|[0-9]|0x[0-9a-fA-F]+|0b[01]+|[0-9]+)(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?$', s):
        return True
    if re.match(r'^\d{4}-\d{2}-\d{2}', s): return False
    if s[0] in '[]{}&*!|>@`': return True
    if ': ' in s or s.startswith(('-', '?', ':')) or ' #' in s: return True
    return False

def yaml_quote_string(s):
    if s == '': return '""'
    if '\n' in s:
        return None
    # use single quotes for flow-looking or colon-space strings, double for implicit scalar words
    if ': ' in s or (s.startswith('{') and s.endswith('}')) or (s.startswith('[') and s.endswith(']')):
        return "'" + s.replace("'", "''") + "'"
    if yaml_plain_danger(s):
        return json_string(s, False)
    return s

def yaml_key(k, no_convert=False):
    if not isinstance(k, str):
        return yaml_scalar(k, no_convert, key=True)
    if not no_convert:
        sf=special_string_to_float(k)
        if sf is not None:
            return yaml_scalar(sf, no_convert, key=True)
    return yaml_quote_string(k)

def yaml_scalar(v, no_convert=False, key=False):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, int) and not isinstance(v,bool): return str(v)
    if isinstance(v, float):
        if math.isnan(v): return '.nan'
        if math.isinf(v): return '.inf' if v>0 else '-.inf'
        # YAML keeps .0 for floats that have it semantically; Python cannot know, but float integral prints with .0.
        return repr(v)
    if isinstance(v, str):
        if not no_convert:
            sf=special_string_to_float(v)
            if sf is not None:
                return yaml_scalar(sf, no_convert, key)
        q=yaml_quote_string(v)
        return q if q is not None else ''
    return yaml_quote_string(str(v))

def dump_yaml(data, no_convert=False, parse_keys=False):
    def write_val(v, indent, keyname=None):
        sp=' '*indent; lines=[]
        if isinstance(v, dict):
            if not v:
                if keyname is not None: return [sp+keyname+': {}']
                return [sp+'{}']
            if keyname is not None: lines.append(sp+keyname+':')
            base = indent+2 if keyname is not None else indent
            for k,val in v.items():
                kk = yaml_key(k, no_convert)
                lines.extend(write_val(val, base, kk))
            return lines
        if isinstance(v, list):
            if keyname is not None: lines.append(sp+keyname+':')
            base=indent+2 if keyname is not None else indent
            if not v:
                if keyname is not None: return [sp+keyname+': []']
                return [sp+'[]']
            for item in v:
                isp=' '*base
                if isinstance(item, dict):
                    if not item:
                        lines.append(isp+'- {}')
                    else:
                        first=True
                        for k,val in item.items():
                            kk=yaml_key(k, no_convert)
                            if first:
                                if isinstance(val,(dict,list)):
                                    lines.append(isp+'- '+kk+':')
                                    lines.extend(write_val(val, base+4, None))
                                else:
                                    if isinstance(val,str) and '\n' in val:
                                        lines.append(isp+'- '+kk+': |-')
                                        lines.extend(' '*(base+4)+ln for ln in val.split('\n'))
                                    else:
                                        lines.append(isp+'- '+kk+': '+yaml_scalar(val,no_convert))
                                first=False
                            else:
                                lines.extend(write_val(val, base+2, kk))
                elif isinstance(item, list):
                    lines.append(isp+'-')
                    lines.extend(write_val(item, base+2, None))
                else:
                    lines.append(isp+'- '+yaml_scalar(item,no_convert))
            return lines
        # scalar
        if isinstance(v, str) and '\n' in v:
            if keyname is not None:
                lines.append(sp+keyname+': |-')
                parts=v.split('\n')
                if parts and parts[-1]=='': parts=parts[:-1]
                lines.extend(' '*(indent+2)+ln for ln in parts)
                return lines
        scalar=yaml_scalar(v,no_convert)
        if keyname is not None:
            return [sp+keyname+': '+scalar]
        return [sp+scalar]
    if parse_keys:
        try:
            data = convert_keys(data)
        except Exception as e:
            # mimic a known failure style loosely
            raise ConvError('Error writing YAML: ' + str(e))
    return '\n'.join(write_val(data,0,None))+'\n'

def convert_keys(obj):
    if isinstance(obj, dict):
        nd={}
        for k,v in obj.items():
            nk=k
            if isinstance(k,str):
                # parse simple scalar keys as YAML values
                nk=YAMLParser('').parse_inline(k)
            nd[nk]=convert_keys(v)
        return nd
    if isinstance(obj, list): return [convert_keys(x) for x in obj]
    return obj

# ---------------- TOML parser/writer ----------------

def toml_split_key(s):
    parts=[]; cur=[]; quote=None; esc=False
    for ch in s.strip():
        if quote:
            cur.append(ch)
            if esc: esc=False
            elif quote=='"' and ch=='\\': esc=True
            elif ch==quote: quote=None
            continue
        if ch in ('"',"'"):
            quote=ch; cur.append(ch); continue
        if ch=='.':
            parts.append(''.join(cur).strip()); cur=[]
        else: cur.append(ch)
    parts.append(''.join(cur).strip())
    return [parse_toml_key(p) for p in parts if p!='']

def parse_toml_key(k):
    k=k.strip()
    if (k.startswith('"') and k.endswith('"')):
        try: return json.loads(k)
        except Exception: return k[1:-1]
    if (k.startswith("'") and k.endswith("'")):
        return k[1:-1]
    return k

def toml_set(root, path, keyparts, val):
    d=root
    for p in path+keyparts[:-1]:
        if p not in d or not isinstance(d[p], dict): d[p]={}
        d=d[p]
    d[keyparts[-1]]=val

def toml_get_table(root, path, array=False):
    d=root
    for i,p in enumerate(path):
        last=(i==len(path)-1)
        if last and array:
            if p not in d or not isinstance(d[p], list): d[p]=[]
            nd={}; d[p].append(nd); return nd
        if p not in d:
            d[p]={}
        elif isinstance(d[p], list):
            if not d[p] or not isinstance(d[p][-1], dict): d[p].append({})
            d=d[p][-1]; continue
        d=d[p]
    return d

def parse_toml_value(s):
    s=s.strip()
    low=s.lower()
    if s.startswith('"""') and s.endswith('"""'):
        return s[3:-3]
    if s.startswith("'''") and s.endswith("'''"):
        return s[3:-3]
    if s.startswith('"') and s.endswith('"'):
        try: return json.loads(s)
        except Exception: return decode_escapes(s[1:-1])
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1]
    if s.startswith('[') and s.endswith(']'):
        inner=s[1:-1].strip()
        if not inner: return []
        return [parse_toml_value(p) for p in split_top(inner)]
    if s.startswith('{') and s.endswith('}'):
        inner=s[1:-1].strip(); d={}
        if inner:
            for p in split_top(inner):
                eq=find_top(p,'=')
                if eq>=0:
                    toml_set(d, [], toml_split_key(p[:eq]), parse_toml_value(p[eq+1:]))
        return d
    if low=='true': return True
    if low=='false': return False
    if low in ('nan','+nan','-nan'): return float('nan')
    if low in ('inf','+inf'): return float('inf')
    if low=='-inf': return float('-inf')
    if re.match(r'^\d{4}-\d{2}-\d{2}', s): return s
    num=s.replace('_','')
    try:
        if re.match(r'^[+-]?\d+$', num): return int(num)
        if re.match(r'^[+-]?(?:\d+\.\d*|\d*\.\d+|\d+(?:\.\d*)?[eE][+-]?\d+)$', num): return float(num)
    except Exception: pass
    return s

def parse_toml_text(text):
    root={}; curpath=[]; cur=root
    try:
        for lineno, raw in enumerate(text.splitlines(),1):
            line=strip_comment(raw).strip()
            if not line: continue
            if line.startswith('[[') and line.endswith(']]'):
                curpath=toml_split_key(line[2:-2])
                cur=toml_get_table(root, curpath, True)
            elif line.startswith('[') and line.endswith(']'):
                curpath=toml_split_key(line[1:-1])
                cur=toml_get_table(root, curpath, False)
            else:
                eq=find_top(line,'=')
                if eq<0:
                    raise ValueError("toml: line %d: expected '.' or '=', but got ':' instead"%lineno)
                key=toml_split_key(line[:eq])
                toml_set(root, curpath, key, parse_toml_value(line[eq+1:]))
        return root
    except ValueError as e:
        raise ConvError('Error parsing TOML: '+str(e))
    except Exception as e:
        raise ConvError('Error parsing TOML: '+str(e))

def toml_key(k):
    s=str(k)
    if re.match(r'^[A-Za-z0-9_-]+$', s): return s
    return json_string(s, False)

def toml_val(v, no_convert=False):
    if v is None: return None
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,int) and not isinstance(v,bool): return str(v)
    if isinstance(v,float):
        if math.isnan(v): return 'nan'
        if math.isinf(v): return '+inf' if v>0 else '-inf'
        return go_float_str(v)
    if isinstance(v,str):
        if not no_convert:
            if v=='NaN': return 'nan'
            if v=='Infinity': return '+inf'
            if v=='-Infinity': return '-inf'
        return json_string(v, False)
    if isinstance(v,list):
        vals=[]
        for x in v:
            if x is None: continue
            if isinstance(x,dict): continue
            tv=toml_val(x,no_convert)
            if tv is not None: vals.append(tv)
        return '['+', '.join(vals)+']'
    return json_string(str(v),False)

def is_table(v): return isinstance(v, dict)
def is_array_table(v): return isinstance(v, list) and any(isinstance(x,dict) for x in v)

def dump_toml(data, no_convert=False, indent=False):
    if not isinstance(data, dict):
        return toml_val(data,no_convert)+'\n'
    lines=[]
    def write_table(d, path, level):
        ind='  '*level if indent else ''
        # primitive values first
        for k,v in d.items():
            if v is None or is_table(v) or is_array_table(v): continue
            tv=toml_val(v,no_convert)
            if tv is not None: lines.append(ind+toml_key(k)+' = '+tv)
        # tables and arrays in input order
        for k,v in d.items():
            if is_table(v):
                if lines and lines[-1] != '': lines.append('')
                hdr='.'.join(toml_key(p) for p in path+[k])
                lines.append(ind+'['+hdr+']')
                write_table(v, path+[k], level+1)
            elif is_array_table(v):
                for item in v:
                    if not isinstance(item,dict): continue
                    if lines and lines[-1] != '': lines.append('')
                    hdr='.'.join(toml_key(p) for p in path+[k])
                    lines.append(ind+'[['+hdr+']]')
                    write_table(item, path+[k], level+1)
    write_table(data, [], 0)
    return '\n'.join(lines)+'\n'

# ---------------- HCL parser/writer ----------------

TOKEN_RE=re.compile(r'\s*(?:("(?:\\.|[^"\\])*")|([A-Za-z_][A-Za-z0-9_\-]*)|([+-]?(?:\d+\.\d*|\d*\.\d+|\d+)(?:[eE][+-]?\d+)?)|(//.*|#.*)|(/\*)|([{}=\[\],]))', re.S)

class HCLLexer:
    def __init__(self,text):
        self.tokens=[]; self.i=0
        self.lex(text)
    def lex(self,text):
        i=0; n=len(text)
        while i<n:
            if text[i].isspace(): i+=1; continue
            if text.startswith('//',i) or text[i]=='#':
                j=text.find('\n',i); i=n if j<0 else j+1; continue
            if text.startswith('/*',i):
                j=text.find('*/',i+2); i=n if j<0 else j+2; continue
            ch=text[i]
            if ch=='"':
                j=i+1; esc=False
                while j<n:
                    if esc: esc=False
                    elif text[j]=='\\': esc=True
                    elif text[j]=='"': break
                    j+=1
                raw=text[i:j+1] if j<n else text[i:]
                try: val=json.loads(raw)
                except Exception: val=raw[1:-1]
                self.tokens.append(('STRING',val)); i=(j+1 if j<n else n); continue
            if ch in '{}[]=,':
                self.tokens.append((ch,ch)); i+=1; continue
            m=re.match(r'[+-]?(?:\d+\.\d*|\d*\.\d+|\d+)(?:[eE][+-]?\d+)?', text[i:])
            if m:
                self.tokens.append(('NUMBER',m.group(0))); i+=len(m.group(0)); continue
            m=re.match(r'[A-Za-z_][A-Za-z0-9_\-]*', text[i:])
            if m:
                self.tokens.append(('IDENT',m.group(0))); i+=len(m.group(0)); continue
            # illegal char ignored for tolerance
            i+=1
    def peek(self): return self.tokens[self.i] if self.i<len(self.tokens) else ('EOF','')
    def pop(self):
        t=self.peek(); self.i+=1; return t
    def accept(self, typ):
        if self.peek()[0]==typ: self.i+=1; return True
        return False
    def expect(self, typ):
        if not self.accept(typ): raise ValueError('expected '+typ)

class HCLParser:
    def __init__(self,text): self.lx=HCLLexer(text)
    def parse(self):
        return self.parse_body(stop=None)
    def parse_body(self, stop='}'):
        d={}
        while self.lx.peek()[0] != 'EOF' and (stop is None or self.lx.peek()[0] != stop):
            tok=self.lx.pop()
            if tok[0] not in ('IDENT','STRING'): continue
            name=tok[1]
            if self.lx.peek()[0]=='=':
                self.lx.pop()
                d[name]=self.parse_expr()
            else:
                labels=[]
                while self.lx.peek()[0] in ('IDENT','STRING','NUMBER'):
                    labels.append(str(self.lx.pop()[1]))
                if self.lx.accept('{'):
                    body=self.parse_body('}')
                    self.lx.accept('}')
                    self.add_block(d,name,labels,body)
        return d
    def add_block(self,d,name,labels,body):
        if not labels:
            d.setdefault(name,[]).append(body); return
        arr=d.setdefault(name,[])
        if not arr or not isinstance(arr[0],dict): arr.insert(0,{})
        cur=arr[0]
        for lab in labels[:-1]:
            a=cur.setdefault(lab,[{}])
            if not a: a.append({})
            cur=a[0]
        cur.setdefault(labels[-1],[]).append(body)
    def parse_expr(self):
        typ,val=self.lx.pop()
        if typ=='STRING': return val
        if typ=='NUMBER':
            return float(val) if any(c in val for c in '.eE') else int(val)
        if typ=='IDENT':
            low=val.lower()
            if low=='true': return True
            if low=='false': return False
            if low=='null': return None
            return val
        if typ=='[':
            arr=[]
            while self.lx.peek()[0] not in (']','EOF'):
                if self.lx.peek()[0]==',': self.lx.pop(); continue
                arr.append(self.parse_expr())
                self.lx.accept(',')
            self.lx.accept(']'); return arr
        if typ=='{':
            body=self.parse_body('}')
            self.lx.accept('}')
            return [body]
        return None

def parse_hcl_text(text):
    try: return HCLParser(text).parse()
    except Exception as e: raise ConvError('Error parsing HCL: '+str(e))

def hcl_scalar(v):
    if v is None: return ''
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,int) and not isinstance(v,bool): return str(v)
    if isinstance(v,float):
        if math.isnan(v): return 'nan'
        if math.isinf(v): return '+inf' if v>0 else '-inf'
        return go_float_str(v)
    if isinstance(v,str): return json_string(v, False)
    return json_string(str(v),False)

def hcl_list(v):
    vals=[]
    for x in v:
        if x is None:
            raise HCLWriteError('unexpected token while parsing list: NULL')
        if isinstance(x,bool):
            continue
        if isinstance(x,dict):
            continue
        if isinstance(x,list):
            vals.append(hcl_list(x))
        else:
            vals.append(hcl_scalar(x))
    return '['+', '.join(vals)+']'

def dump_hcl(data):
    def write_value(v, indent):
        if isinstance(v, dict):
            inner=write_body(v, indent+2)
            if inner:
                return '{\n'+inner+'\n'+' '*indent+'}'
            return '{}'
        if isinstance(v, list):
            if any(isinstance(x,dict) for x in v):
                # caller handles repeated objects; for nested scalar fallback list
                return hcl_list(v)
            return hcl_list(v)
        return hcl_scalar(v)
    def write_body(d, indent):
        lines=[]; first=True
        for k,v in d.items():
            if not first: lines.append('')
            first=False
            sp=' '*indent; key=json_string(str(k),False)
            if isinstance(v,list) and any(isinstance(x,dict) for x in v):
                firstobj=True
                for obj in v:
                    if not isinstance(obj,dict): continue
                    if not firstobj: lines.append('')
                    firstobj=False
                    lines.append(sp+key+' = '+write_value(obj, indent))
            else:
                lines.append(sp+key+' = '+write_value(v, indent))
        return '\n'.join(lines)
    try:
        if isinstance(data, dict): return write_body(data,0)
        return write_value(data,0)
    except HCLWriteError as e:
        raise ConvError('Error writing HCL: '+str(e))

# ---------------- main/flags ----------------

def help_text(prog):
    return f"""Usage: {prog} [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version
"""

def parse_flags(args):
    valid=set('ytjcrneikhv')
    invalid=[]; opts=set(); conv=[]
    for arg in args:
        for ch in arg:
            if ch=='-': continue
            if ch not in valid:
                if ch not in invalid: invalid.append(ch)
            else:
                if ch in 'neikhv': opts.add(ch)
                if ch in 'ytjcr':
                    if ch=='r': conv.extend(['j','y'])
                    else: conv.append(ch)
    if invalid:
        return None, opts, invalid
    if len(conv)==0:
        inp,out='y','j'
    elif len(conv)==1:
        if conv[0] in ('y','t','c'): inp,out=conv[0],'j'
        elif conv[0]=='j': inp,out='j','j'
        else: inp,out='y','j'
    else:
        inp,out=conv[-2],conv[-1]
    return (inp,out), opts, []

def usage_error(prog, msg):
    sys.stderr.write(help_text(prog)+'\nError: '+msg+'\n')
    return 1

def main():
    prog=sys.argv[0]
    conv, opts, invalid = parse_flags(sys.argv[1:])
    if invalid:
        return usage_error(prog, 'invalid flags specified: '+' '.join(invalid))
    if 'h' in opts:
        sys.stdout.write(help_text(prog)); return 0
    if 'v' in opts:
        sys.stdout.write('v0.0.0\n'); return 0
    inp,out=conv
    if 'i' in opts and out not in ('j','t'):
        return usage_error(prog, 'flag -i only valid for JSON or TOML output')
    if 'k' in opts and out!='y':
        return usage_error(prog, 'flag -k only valid for YAML output')
    if 'e' in opts and out!='j':
        return usage_error(prog, 'flag -e only valid for JSON output')
    text=sys.stdin.read()
    try:
        if inp=='j': data=parse_json_text(text)
        elif inp=='y': data=parse_yaml_text(text)
        elif inp=='t': data=parse_toml_text(text)
        elif inp=='c': data=parse_hcl_text(text)
        else: data=parse_yaml_text(text)
        no_convert = 'n' in opts
        if out=='j':
            sys.stdout.write(dump_json(prepare_json_value(data,no_convert), 'i' in opts, 'e' in opts))
        elif out=='y':
            sys.stdout.write(dump_yaml(data,no_convert,'k' in opts))
        elif out=='t':
            sys.stdout.write(dump_toml(data,no_convert,'i' in opts))
        elif out=='c':
            sys.stdout.write(dump_hcl(data))
        return 0
    except ConvError as e:
        sys.stderr.write(str(e)+'\n'); return 1

if __name__ == '__main__':
    sys.exit(main())
